-- [TABLE_READ] Step: read_SOR_HOM_CON_CNTR_REF
-- Table: SOR_HOM_CON_CNTR_REF
-- Connection: SOR
SELECT * FROM SOR_HOM_CON_CNTR_REF;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_CON_CNTR_REF
select m.cntr_mgr_post_desp, dense_rank()
  over (
		 order by m.cntr_mgr_post_desp
       ) cntr_mgr_disp_seq_num
  from (
		select distinct v.CNTR_MGR_POST_DESP
		  from SOR_HOM_CON_CNTR_REF v
		 where v.del_ind        = 'N'
		   and v.CNTR_MGR_POST_DESP is not null
		 union 
		select distinct cs.CNTR_MGR_POST
		  from SOR_HOM_PRG_SNSH_CNTR c, SOR_HOM_PRG_SNSH_CNTR_STS cs, SOR_HOM_PRG_SNSH s, SOR_HOM_PRG_SNSH_STS ss
		 where c.LAST_REC_TXN_TYPE_CODE is null
		   and cs.LAST_REC_TXN_TYPE_CODE is null
		   and s.LAST_REC_TXN_TYPE_CODE is null
		   and ss.LAST_REC_TXN_TYPE_CODE is null
		   and s.snsh_key = ss.snsh_key
		   and c.snsh_key = s.snsh_key
		   and c.PGM_LVL_SNSH_CNTR_KEY = cs.PGM_LVL_SNSH_CNTR_KEY
		   and ss.snsh_type_code = 'FINAL'
		   and ss.snsh_qtr_ind   = 'N'
		   and cs.cntr_mgr_post is not null
		   and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN cs.bgn_date AND cs.end_date
		   and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN ss.bgn_date AND ss.end_date
       ) m
 union 
select 'Others' cntr_mgr_post, 99999 cntr_mgr_disp_seq_num
  from dual;

