-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_SMT_KPI_TYPE_CODE
select distinct c.kpi_type_code, cc.kpi_type_desp,
       t.kpi_type_tac, tt.kpi_type_trgt_actl_desp
  from SOR_HOM_SMT_KPI_INPT_MSR m, SOR_HOM_SMT_KPI_INPT_MSR_STS mm, 
       SOR_HOM_SMT_KPI_TYPE_CODE c, SOR_HOM_SMT_KPI_TYPE_CODE_STS cc,
       SOR_HOM_SMT_KPI_TYPE_TAC t, SOR_HOM_SMT_KPI_TYPE_TAC_STS tt
 where m.last_rec_txn_type_code is null
   and mm.last_rec_txn_type_code is null
   and c.last_rec_txn_type_code is null
   and cc.last_rec_txn_type_code is null
   and t.last_rec_txn_type_code is null
   and tt.last_rec_txn_type_code is null
   and m.KPI_INPT_MSR_KEY = mm.KPI_INPT_MSR_KEY
   and c.kpi_type_key = cc.kpi_type_key
   and t.KPI_TYPE_TRGT_ACTL_KEY = tt.KPI_TYPE_TRGT_ACTL_KEY	
   and m.kpi_type_key = c.kpi_type_key
   and m.KPI_TYPE_TRGT_ACTL_KEY = t.KPI_TYPE_TRGT_ACTL_KEY
   and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN mm.bgn_date AND mm.end_date
   and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN cc.bgn_date AND cc.end_date
   and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN tt.bgn_date AND tt.end_date
   order by c.kpi_type_code, t.kpi_type_tac;

