-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_REF_DSTR
select nvl(g.DSTR_GRP_CODE,'OTHR') dstr_grp_code,
       nvl(gg.DSTR_GRP_NAME, 'Others') dstr_grp_name, d.dstr_code,
       dd.dstr_name, decode(
	       d.dstr_code, 'OR', 1000, 'UN', 2000, gg.DISP_SEQ_NUM
       ) dstr_grp_disp_seq_num, decode( d.dstr_code, 'OR', 1000, 'UN', 2000, dd.DISP_SEQ_NUM) dstr_disp_seq_num
  from SOR_HOM_REF_DSTR d, SOR_HOM_REF_DSTR_sts dd,
       SOR_HOM_REF_DSTR_GRP g, SOR_HOM_REF_DSTR_GRP_sts gg
 where dd.dstr_grp_code = g.dstr_grp_code(+)
       and d.dstr_key = dd.dstr_key
	   and g.dstr_grp_key = gg.dstr_grp_key(+)
	   and (TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN dd.bgn_date AND dd.end_date or dd.bgn_date is null)
	   and (TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN gg.bgn_date AND gg.end_date or gg.bgn_date is null)
 union 
select 'OTHR' dstr_grp_code, 'Others' dstr_grp_name, 'OTHR' dstr_code,
       'Others' dstr_name, 1000 dstr_grp_disp_seq_num, 10000 dstr_disp_seq_num
  from dual;

