-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_BUD_COPY
select a.dmns_year dmns_year
, a.dmns_mth dmns_mth
, a.disp_fin_year_text disp_fin_year_text
, a.disp_mth_text disp_mth_text
, a.disp_qtr_text disp_qtr_text
, dense_rank() over (order by a.dmns_year, a.dmns_mth) mth_disp_seq_num
from
(
select
to_number(to_char(add_months(d.cur_date, m.add_mth + y.add_year * 12), 'YYYY')) dmns_year
, to_number(to_char(add_months(d.cur_date, m.add_mth + y.add_year * 12), 'MM')) dmns_mth
, to_char(add_months(add_months(d.cur_date, m.add_mth + y.add_year * 12), -3), 'YYYY')||' - '|| (to_number(to_char(add_months(add_months(d.cur_date, m.add_mth + y.add_year * 12), -3), 'YYYY'))+1) disp_fin_year_text
, to_char(add_months(d.cur_date, m.add_mth + y.add_year * 12), 'YYYY ') ||' ' ||decode(to_char(add_months(d.cur_date, m.add_mth + y.add_year * 12), 'MM'), '01', 'Jan', '02', 'Feb', '03', 'Mar', '04', 'Apr', '05', 'May', '06', 'Jun', '07', 'Jul', '08', 'Aug', '09', 'Sep', '10', 'Oct', '11', 'Nov', '12', 'Dec') disp_mth_text
, to_char(add_months(d.cur_date, m.add_mth + y.add_year * 12), 'YYYY ') || ' '||decode(to_char(add_months(d.cur_date, m.add_mth + y.add_year * 12), 'MM'), '01', 'Jan - Mar', '02', 'Jan - mar', '03', 'Jan - mar', '04', 'Apr - Jun', '05', 'Apr - Jun', '06', 'Apr - Jun', '07', 'Jul - Sep', '08', 'Jul - Sep', '09', 'Jul - Sep', '10', 'Oct - Dec', '11', 'Oct - Dec', '12', 'Oct - Dec') disp_qtr_text
from
(
 select sysdate cur_date
 from dual
) d
,(
  select 1 add_mth from dual union all
  select 2 add_mth from dual union all
  select 3 add_mth from dual union all
  select 4 add_mth from dual union all
  select 5 add_mth from dual union all
  select 6 add_mth from dual union all
  select 7 add_mth from dual union all
  select 8 add_mth from dual union all
  select 9 add_mth from dual union all
  select 10 add_mth from dual union all
  select 11 add_mth from dual union all
  select 12 add_mth from dual
) m
,(
  select 0 add_year from dual union all
  select 1 add_year from dual union all
  select 2 add_year from dual union all
  select 3 add_year from dual union all
  select 4 add_year from dual union all
  select 5 add_year from dual union all
  select 6 add_year from dual union all
  select 7 add_year from dual union all
  select 8 add_year from dual union all
  select 9 add_year from dual union all
  select 10 add_year from dual union all
  select 11 add_year from dual union all
  select 12 add_year from dual union all
  select 13 add_year from dual union all
  select 14 add_year from dual union all
  select 15 add_year from dual union all
  select 16 add_year from dual union all
  select 17 add_year from dual union all
  select 18 add_year from dual union all
  select 19 add_year from dual union all
  select 20 add_year from dual union all
  select 21 add_year from dual union all
  select 22 add_year from dual union all
  select 23 add_year from dual union all
  select 24 add_year from dual union all
  select 25 add_year from dual union all
  select -1 add_year from dual union all
  select -2 add_year from dual union all
  select -3 add_year from dual union all
  select -4 add_year from dual union all
  select -5 add_year from dual union all
  select -6 add_year from dual union all
  select -7 add_year from dual union all
  select -8 add_year from dual union all
  select -9 add_year from dual union all
  select -10 add_year from dual union all
  select -11 add_year from dual union all
  select -12 add_year from dual union all
  select -13 add_year from dual union all
  select -14 add_year from dual union all
  select -15 add_year from dual union all
  select -16 add_year from dual union all
  select -17 add_year from dual union all
  select -18 add_year from dual union all
  select -19 add_year from dual union all
  select -20 add_year from dual union all
  select -21 add_year from dual union all
  select -22 add_year from dual union all
  select -23 add_year from dual union all
  select -24 add_year from dual union all
  select -25 add_year from dual
) y
union
select
to_number(to_char(add_months(d.cur_date, m.add_mth + y.add_year * 12), 'YYYY')) dmns_year
, 0 dmns_mth
, to_char(add_months(add_months(d.cur_date, m.add_mth + y.add_year * 12), -3), 'YYYY')||' - '||(to_number(to_char(add_months(add_months(d.cur_date, m.add_mth + y.add_year * 12), -3), 'YYYY'))+1) disp_fin_year_text
, to_char(add_months(add_months(d.cur_date, m.add_mth + y.add_year * 12), -3), 'YYYY')||' - '||(to_number(to_char(add_months(add_months(d.cur_date, m.add_mth + y.add_year * 12), -3), 'YYYY'))+1) disp_mth_text
, to_char(add_months(add_months(d.cur_date, m.add_mth + y.add_year * 12), -3), 'YYYY')||' - '||(to_number(to_char(add_months(add_months(d.cur_date, m.add_mth + y.add_year * 12), -3), 'YYYY'))+1) disp_qtr_text
from
(
 select sysdate cur_date
 from dual
) d
,(
  select 0 add_mth from dual
) m
,(
  select 0 add_year from dual union all
  select 1 add_year from dual union all
  select 2 add_year from dual union all
  select 3 add_year from dual union all
  select 4 add_year from dual union all
  select 5 add_year from dual union all
  select 6 add_year from dual union all
  select 7 add_year from dual union all
  select 8 add_year from dual union all
  select 9 add_year from dual union all
  select 10 add_year from dual union all
  select 11 add_year from dual union all
  select 12 add_year from dual union all
  select 13 add_year from dual union all
  select 14 add_year from dual union all
  select 15 add_year from dual union all
  select 16 add_year from dual union all
  select 17 add_year from dual union all
  select 18 add_year from dual union all
  select 19 add_year from dual union all
  select 20 add_year from dual union all
  select 21 add_year from dual union all
  select 22 add_year from dual union all
  select 23 add_year from dual union all
  select 24 add_year from dual union all
  select 25 add_year from dual union all
  select -1 add_year from dual union all
  select -2 add_year from dual union all
  select -3 add_year from dual union all
  select -4 add_year from dual union all
  select -5 add_year from dual union all
  select -6 add_year from dual union all
  select -7 add_year from dual union all
  select -8 add_year from dual union all
  select -9 add_year from dual union all
  select -10 add_year from dual union all
  select -11 add_year from dual union all
  select -12 add_year from dual union all
  select -13 add_year from dual union all
  select -14 add_year from dual union all
  select -15 add_year from dual union all
  select -16 add_year from dual union all
  select -17 add_year from dual union all
  select -18 add_year from dual union all
  select -19 add_year from dual union all
  select -20 add_year from dual union all
  select -21 add_year from dual union all
  select -22 add_year from dual union all
  select -23 add_year from dual union all
  select -24 add_year from dual union all
  select -25 add_year from dual
) y
) a
union
select 9999 dmns_year, 99 dmns_mth, 'N/A' disp_fin_year_text, 'N/A' disp_mth_text, 'N/A' disp_qtr_text, 9999 mth_disp_seq_num from dual
union
select y.prcs_year+1000 dmns_year
, 0 dmns_mth
, 'Post '||to_char(y.prcs_year+9)||'/'||substr(to_char(y.prcs_year+10), 3) disp_fin_year_text
, 'Post '||to_char(y.prcs_year+9)||'/'||substr(to_char(y.prcs_year+10), 3) disp_mth_text
, 'Post '||to_char(y.prcs_year+9)||'/'||substr(to_char(y.prcs_year+10), 3) disp_qtr_text
, 999 + dense_rank() over (order by y.prcs_year) mth_disp_seq_num
from
(
select to_number(p.parm_text) prcs_year
from SOR_HOM_BUD_PARM_STS p
where p.PARM_NAME = 'PRCS_YEAR'
and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN p.bgn_date AND p.end_date
union
select distinct first_value(c.prcs_year) over (order by c.prcs_year desc) prcs_year
from SOR_HOM_BUD_COPY c
where c.LAST_REC_TXN_TYPE_CODE is NULL
and c.bdgt_exrc_code = '0'
and c.copy_code = 'C'
and c.copy_ver_num = -1
) y;

