-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_REF_FIN_NTR
select f.fin_ntr_code, fs.fin_ntr_desp, fs.DISP_SEQ_NUM fin_ntr_disp_seq_num
  from SOR_HOM_REF_FIN_NTR f, SOR_HOM_REF_FIN_NTR_STS fs
 where f.FIN_NTR_KEY = fs.FIN_NTR_KEY
   and f.LAST_REC_TXN_TYPE_CODE is null
   and fs.LAST_REC_TXN_TYPE_CODE is null
