-- [TABLE_READ] Step: read_SOR_HOM_PRG_SNSH
-- Table: SOR_HOM_PRG_SNSH
-- Connection: SOR
SELECT * FROM SOR_HOM_PRG_SNSH;

-- [TABLE_READ] Step: read_SOR_HOM_PRG_SNSH_STS
-- Table: SOR_HOM_PRG_SNSH_STS
-- Connection: SOR
SELECT * FROM SOR_HOM_PRG_SNSH_STS;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_PRG_SNSH
select snsh.snsh_year, snsh.snsh_mth,
          snsh.disp_fin_year_text, snsh.disp_snsh_year_text
	      from (
		   select snsh_year, snsh_mth, disp_fin_year_text, disp_snsh_year_text
		   from (
				 select ss.snsh_year, ss.snsh_mth,
					  to_char(to_number(to_char(add_months(ss.snsh_as_at_date, -3), 'YYYY'
							  )))||' - '||to_char(to_number(to_char(add_months(ss.snsh_as_at_date, -3), 'YYYY'
					  ))+1) disp_fin_year_text, to_char(ss.snsh_as_at_date, 'YYYY ') ||
					  decode(
						  to_char(ss.snsh_as_at_date,
						  'MM'), '01', 'Jan',
						  '02', 'Feb', '03', 'Mar', '04',
						  'Apr', '05', 'May', '06', 'Jun',
						  '07', 'Jul', '08', 'Aug', '09',
						  'Sep', '10', 'Oct', '11', 'Nov',
						  '12', 'Dec'
					   ) disp_snsh_year_text
				  from SOR_HOM_PRG_SNSH s, SOR_HOM_PRG_SNSH_sts ss
				  where s.last_rec_txn_type_code is null
				      and ss.last_rec_txn_type_code is null
					  and s.snsh_key = ss.snsh_key
					  and ss.snsh_type_code    = 'FINAL'
				      and ss.snsh_qtr_ind      = 'N'
				      and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN ss.bgn_date AND ss.end_date
				      and s.snsh_hom_key in (
						   select distinct first_value(snsh.snsh_hom_key)
						     over (
							    partition by to_char(add_months(snshs.snsh_as_at_date, -3), 'YYYY')
							    order by add_months(snshs.snsh_as_at_date, -3) desc
							      )
						   from SOR_HOM_PRG_SNSH snsh, SOR_HOM_PRG_SNSH_sts snshs
						   where snsh.last_rec_txn_type_code is null
						      and snshs.snsh_key = snsh.snsh_key
						      and snshs.snsh_type_code = 'FINAL'
						      and snshs.snsh_qtr_ind   = 'N'
						      and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN snshs.bgn_date AND snshs.end_date
					                    )
			     )
		    union (
				   select ss.snsh_year + 1 snsh_year, ss.snsh_mth,
					      to_char(
						  to_number(
							  to_char(
								  add_months(
									  ss.snsh_as_at_date, -3
								  ), 'YYYY'
							  )
					  )+1)||' - '||
					  to_char(
						  to_number(
							  to_char(
								  add_months(
									  ss.snsh_as_at_date, -3
								  ), 'YYYY'
					  ))+2) disp_fin_year_text,
					  to_char(
						  to_date(
							  ss.snsh_year+1||
							  to_char(ss.snsh_mth, '00'), 'YYYYMM'
						  ), 'YYYY '
					  ) ||
					  decode(
						  to_char(
							  to_date(
								  ss.snsh_year+1||
								  to_char(
									  ss.snsh_mth, '00'
								  ), 'YYYYMM'
							  ), 'MM'
						  ), '01', 'Jan', '02',
						  'Feb', '03', 'Mar', '04', 'Apr', '05',
						  'May', '06', 'Jun', '07', 'Jul', '08',
						  'Aug', '09', 'Sep', '10', 'Oct', '11',
						  'Nov', '12', 'Dec'
					  ) disp_snsh_year_text
				   from SOR_HOM_PRG_SNSH s, SOR_HOM_PRG_SNSH_sts ss
				   where s.last_rec_txn_type_code is null
				      and s.snsh_key = ss.snsh_key
				      and ss.snsh_type_code    = 'FINAL'
				      and ss.snsh_qtr_ind      = 'N'
				      and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN ss.bgn_date AND ss.end_date
				      and s.snsh_hom_key in (
						   select distinct first_value(snsh.snsh_hom_key)
						     over (
								    order by add_months(snshs.snsh_as_at_date, -3) desc
							      )
						     from SOR_HOM_PRG_SNSH snsh, SOR_HOM_PRG_SNSH_sts snshs
						    where snsh.last_rec_txn_type_code is null
							  and snshs.last_rec_txn_type_code is null
							  and snsh.snsh_key = snshs.snsh_key
						      and snshs.snsh_type_code = 'FINAL'
						      and snshs.snsh_qtr_ind   = 'N'
						      and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN snshs.bgn_date AND snshs.end_date
					                     )
			  )
		    union (
				   select 9999 snsh_year, 12
				          snsh_mth, 'Others'
				          disp_fin_year_text, 'Others'
				          disp_snsh_year_text
				     from dual
			      )
          ) snsh;

