-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_BUD_COPY
select	prcs_year
				,prcs_mth
				,TO_DATE('01/'||prcs_mth||'/'||prcs_year,'dd/mm/yyyy') prcs_date
				,prcs_year||' - '||TO_CHAR(prcs_year+1) prcs_year_text
				,TO_CHAR(TO_DATE('01/'||cldr_mth||'/'||cldr_year,'dd/mm/yyyy'),'Month') prcs_mth_text
				,dense_rank() over (order by prcs_year) prcs_year_disp_seq_num
				,dense_rank() over (order by prcs_mth) prcs_mth_disp_seq_num
from
(
		select	d.prcs_year+y.add_year prcs_year
						,m.mth prcs_mth
						,DECODE(MOD(m.mth+3,12),1,d.prcs_year+y.add_year+1,2,d.prcs_year+y.add_year+1,3,d.prcs_year+y.add_year+1,d.prcs_year+y.add_year) cldr_year
						,DECODE(MOD(m.mth+3,12),0,12,MOD(m.mth+3,12)) cldr_mth
		from
		(
		 select MIN(prcs_year) prcs_year
		 from 	SOR_HOM_BUD_COPY
		 where	last_rec_txn_type_code is null
		 and		prcs_year <> -1
		) d
		,(
		  select 1 mth from dual union all
		  select 2 mth from dual union all
		  select 3 mth from dual union all
		  select 4 mth from dual union all
		  select 5 mth from dual union all
		  select 6 mth from dual union all
		  select 7 mth from dual union all
		  select 8 mth from dual union all
		  select 9 mth from dual union all
		  select 10 mth from dual union all
		  select 11 mth from dual union all
		  select 12 mth from dual
		) m
		,(
		  select 0 add_year from dual union all
		  select 1 add_year from dual union all
		  select 2 add_year from dual union all
		  select 3 add_year from dual union all
		  select 4 add_year from dual union all
		  select 5 add_year from dual union all
		  select 6 add_year from dual union all
		  select 7 add_year from dual union all
		  select 8 add_year from dual union all
		  select 9 add_year from dual union all
		  select 10 add_year from dual union all
		  select 11 add_year from dual union all
		  select 12 add_year from dual union all
		  select 13 add_year from dual union all
		  select 14 add_year from dual union all
		  select 15 add_year from dual union all
		  select 16 add_year from dual union all
		  select 17 add_year from dual union all
		  select 18 add_year from dual union all
		  select 19 add_year from dual union all
		  select 20 add_year from dual
		) y
);

