-- Connection: SOR
SELECT * FROM SOR_HOM_BUD_COPY;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_BUD_PARM
select a.prcs_year_num, a.prcs_year_text, dense_rank()
  over (
		 order by (a.prcs_year_num)
       ) year_disp_seq_num
  from (
		select y.cur_year + a.add_year prcs_year_num,
		       to_char(y.cur_year + a.add_year)||' - '||
		       to_char(y.cur_year + a.add_year + 1) prcs_year_text
		  from (
				select to_number(to_char(sysdate, 'YYYY')) cur_year
				  from dual
		       ) y,(
				select 0 add_year
				  from dual
				 union all
				select 1 add_year
				  from dual
				 union all
				select 2 add_year
				  from dual
				 union all
				select 3 add_year
				  from dual
				 union all
				select 4 add_year
				  from dual
				 union all
				select 5 add_year
				  from dual
				 union all
				select 6 add_year
				  from dual
				 union all
				select 7 add_year
				  from dual
				 union all
				select 8 add_year
				  from dual
				 union all
				select 9 add_year
				  from dual
				 union all
				select 10 add_year
				  from dual
				 union all
				select 11 add_year
				  from dual
				 union all
				select 12 add_year
				  from dual
				 union all
				select 13 add_year
				  from dual
				 union all
				select 14 add_year
				  from dual
				 union all
				select 15 add_year
				  from dual
				 union all
				select 16 add_year
				  from dual
				 union all
				select 17 add_year
				  from dual
				 union all
				select 18 add_year
				  from dual
				 union all
				select 19 add_year
				  from dual
				 union all
				select 20 add_year
				  from dual
				 union all
				select 21 add_year
				  from dual
				 union all
				select 22 add_year
				  from dual
				 union all
				select 23 add_year
				  from dual
				 union all
				select 24 add_year
				  from dual
				 union all
				select 25 add_year
				  from dual
				 union all
				select -1 add_year
				  from dual
				 union all
				select -2 add_year
				  from dual
				 union all
				select -3 add_year
				  from dual
				 union all
				select -4 add_year
				  from dual
				 union all
				select -5 add_year
				  from dual
				 union all
				select -6 add_year
				  from dual
				 union all
				select -7 add_year
				  from dual
				 union all
				select -8 add_year
				  from dual
				 union all
				select -9 add_year
				  from dual
				 union all
				select -10 add_year
				  from dual
				 union all
				select -11 add_year
				  from dual
				 union all
				select -12 add_year
				  from dual
				 union all
				select -13 add_year
				  from dual
				 union all
				select -14 add_year
				  from dual
				 union all
				select -15 add_year
				  from dual
				 union all
				select -16 add_year
				  from dual
				 union all
				select -17 add_year
				  from dual
				 union all
				select -18 add_year
				  from dual
				 union all
				select -19 add_year
				  from dual
				 union all
				select -20 add_year
				  from dual
				 union all
				select -21 add_year
				  from dual
				 union all
				select -22 add_year
				  from dual
				 union all
				select -23 add_year
				  from dual
				 union all
				select -24 add_year
				  from dual
				 union all
				select -25 add_year
				  from dual
		       ) a
		 union 
		select y.prcs_year+1000 prcs_year, 'Post '||to_char(y.prcs_year+9)||' - '||
		       to_char(y.prcs_year+10) prcs_year_text
		  from (
				select to_number(pp.parm_text) prcs_year
				  from SOR_HOM_BUD_PARM p, SOR_HOM_BUD_PARM_STS pp
				 where pp.PARM_NAME      = 'PRCS_YEAR'
				 and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN pp.bgn_date AND pp.end_date
				 union 
				select distinct first_value(c.prcs_year)
				  over (
						 order by c.prcs_year desc
				       ) prcs_year
				  from SOR_HOM_BUD_COPY c
				 where c.last_rec_txn_type_code is null
				   and c.bdgt_exrc_code = '0'
				   and c.copy_code      = 'C'
				   and c.copy_ver_num   = -1
		       ) y
       ) a;

