-- Connection: SOR
SELECT * FROM SOR_HOM_REF_DSTR_STS;

-- [TABLE_READ] Step: read_SOR_HOM_REF_RGN
-- Table: SOR_HOM_REF_RGN
-- Connection: SOR
SELECT * FROM SOR_HOM_REF_RGN;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_REF_DSTR
select decode(g.rgn_code,'?','OTHR', g.rgn_code) rgn_code, nvl(gg.rgn_name, 'Others')
       rgn_name, d.dstr_code, dd.dstr_name, decode(d.dstr_code, 'OR', 1000, gg.DISP_SEQ_NUM) rgn_disp_seq_num,
       decode(d.dstr_code, 'OR', 1000, 'UN', 2000, dd.DISP_SEQ_NUM) dstr_disp_seq_num
  from SOR_HOM_REF_DSTR d, SOR_HOM_REF_DSTR_STS dd, 
       SOR_HOM_REF_RGN g, SOR_HOM_REF_RGN_STS gg
 where dd.rgn_key = g.rgn_key(+)
       and g.rgn_key = gg.rgn_key (+)
	   and d.dstr_key = dd.dstr_key
	   and (TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN dd.bgn_date AND dd.end_date or dd.bgn_date is null)
	   and (TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN gg.bgn_date AND gg.end_date or gg.bgn_date is null)
 union 
select 'OTHR' rgn_code, 'Others' rgn_name, 'OTHR' dstr_code, 'Others'
       dstr_name, 1000 rgn_disp_seq_num, 10000 dstr_disp_seq_num
  from dual;

