-- Table: SOR_HOM_PRG_SNSH_STS
-- Connection: SOR
SELECT * FROM SOR_HOM_PRG_SNSH_STS;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_PRG_SNSH_CNTR
select
c.cntr_hom_key cntr_key
, s.snsh_hom_key snsh_key
, nvl(cc.cntr_num, cc.tndr_num) cntr_num
, nvl(cc.cntr_ttl, cc.tndr_ttl) cntr_ttl
, dense_rank() over (order by ss.snsh_year, ss.snsh_mth, cc.cntr_ttl, c.cntr_hom_key) snsh_cntr_disp_seq_num
from SOR_HOM_PRG_SNSH_CNTR c, SOR_HOM_PRG_SNSH_CNTR_STS cc, SOR_HOM_PRG_SNSH s, SOR_HOM_PRG_SNSH_STS ss
where s.last_rec_txn_type_code is null
and ss.last_rec_txn_type_code is null
and c.last_rec_txn_type_code is null
and cc.last_rec_txn_type_code is null
and ss.snsh_type_code = 'FINAL'
and ss.snsh_qtr_ind = 'N'
and c.snsh_key = s.snsh_key
and s.snsh_key = ss.snsh_key 
and c.PGM_LVL_SNSH_CNTR_KEY = cc.pgm_lvl_snsh_cntr_key
and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN cc.bgn_date AND cc.end_date
and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN ss.bgn_date AND ss.end_date;

