-- =============================================================================
-- Mapping: M_DPA_SUMMARIZE_DMNS_KPI_SNSH_MTH
-- =============================================================================

-- [TABLE_READ] Step: read_SOR_HOM_PRG_SNSH
-- Table: SOR_HOM_PRG_SNSH
-- Connection: SOR
SELECT * FROM SOR_HOM_PRG_SNSH;

-- [TABLE_READ] Step: read_SOR_HOM_PRG_SNSH_STS
-- Table: SOR_HOM_PRG_SNSH_STS
-- Connection: SOR
SELECT * FROM SOR_HOM_PRG_SNSH_STS;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_PRG_SNSH
select to_char(ss.SNSH_YEAR) dmns_year, to_char(ss.snsh_mth) dmns_mth,
       to_char(add_months(ss.SNSH_AS_AT_DATE, -3), 'YYYY')||' - '||
       to_char(
	       add_months(
		       add_months(
			       ss.SNSH_AS_AT_DATE, -3
		       ), 12
	       ), 'YYYY'
       ) disp_fin_year_text, to_char(ss.SNSH_AS_AT_DATE, 'YYYY')||' '||
       decode(
	       trim(to_char(ss.snsh_mth, '00')), '01', 'Jan', '02', 'Feb',
	       '03', 'Mar', '04', 'Apr', '05', 'May', '06', 'Jun', '07', 'Jul', '08',
	       'Aug', '09', 'Sep', '10', 'Oct', '11', 'Nov', '12', 'Dec'
       ) disp_mth_text, to_char(add_months(ss.SNSH_AS_AT_DATE, -3), 'YYYY')||'
       - '||
       to_char(add_months(add_months(ss.SNSH_AS_AT_DATE, -3), 12), 'YYYY')||' '||
       decode(
	       trim(to_char(ss.snsh_mth, '00')),'01', 'Jan-Mar', '02',
	       'Jan-Mar', '03', 'Jan-Mar', '04', 'Apr-Jun', '05', 'Apr-Jun', '06',
	       'Apr-Jun', '07', 'Jul-Sep', '08', 'Jul-Sep', '09', 'Jul-Sep', '10',
	       'Oct-Dec', '11', 'Oct-Dec', '12', 'Oct-Dec'
       ) disp_qtr_text, dense_rank()
  over (
		 order by ss.snsh_year, ss.snsh_mth
       ) mth_disp_seq_num
  from SOR_HOM_PRG_SNSH s, SOR_HOM_PRG_SNSH_sts ss
 where s.last_rec_txn_type_code is null
   and ss.last_rec_txn_type_code is null
   and s.snsh_key = ss.snsh_key
   and ss.snsh_type_code = 'FINAL'
   and ss.snsh_qtr_ind   = 'N'
   and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN ss.bgn_date AND ss.end_date
 union 
select to_char(ss.SNSH_YEAR+1) dmns_year, to_char(ss.snsh_mth) dmns_mth,
       to_char(
	       add_months(
		       add_months(ss.SNSH_AS_AT_DATE, -3), 12
	       ), 'YYYY'
       )||' - '||
       to_char(
	       add_months(
		       add_months(
			       ss.SNSH_AS_AT_DATE, -3
		       ), 24
	       ), 'YYYY'
       ) disp_fin_year_text,
       to_char(add_months(add_months(ss.SNSH_AS_AT_DATE, -3), 12), 'YYYY')||' '||
       decode(
	       trim(to_char(ss.snsh_mth, '00')), '01', 'Jan', '02', 'Feb',
	       '03', 'Mar', '04', 'Apr', '05', 'May', '06', 'Jun', '07', 'Jul', '08',
	       'Aug', '09', 'Sep', '10', 'Oct', '11', 'Nov', '12', 'Dec'
       ) disp_mth_text,
       to_char(add_months(add_months(ss.SNSH_AS_AT_DATE, -3), 12), 'YYYY')||'
       - '||
       to_char(
	       add_months(add_months(ss.SNSH_AS_AT_DATE, -3), 24), 'YYYY'
       )||' '|| decode(trim(to_char(ss.snsh_mth, '00')),'01', 'Jan-Mar', '02',
       'Jan-Mar', '03', 'Jan-Mar', '04', 'Apr-Jun', '05', 'Apr-Jun', '06',
       'Apr-Jun',
       '07', 'Jul-Sep', '08', 'Jul-Sep', '09', 'Jul-Sep', '10', 'Oct-Dec', '11',
       'Oct-Dec', '12', 'Oct-Dec') disp_qtr_text, 999999 mth_disp_seq_num
  from SOR_HOM_PRG_SNSH s, SOR_HOM_PRG_SNSH_sts ss
 where s.last_rec_txn_type_code is null
   and s.last_rec_txn_type_code is null
   and s.snsh_key = ss.snsh_key
   and ss.snsh_type_code = 'FINAL'
   and ss.snsh_qtr_ind   = 'N'
   and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN ss.bgn_date AND ss.end_date
   and s.snsh_hom_key       = (
		select distinct first_value(s.snsh_hom_key)
		  over (
				 order by ss.SNSH_YEAR desc, ss.snsh_mth desc
		       )
		  from SOR_HOM_PRG_SNSH s, SOR_HOM_PRG_SNSH_sts ss
		 where s.last_rec_txn_type_code is null
		   and s.last_rec_txn_type_code is null
		   and s.snsh_key = ss.snsh_key
		   and ss.snsh_type_code = 'FINAL'
		   and ss.snsh_qtr_ind   = 'N'
		   and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN ss.bgn_date AND ss.end_date
       );

