-- Table: SOR_HOM_BUD_COPY
-- Connection: SOR
SELECT * FROM SOR_HOM_BUD_COPY;

-- [TABLE_READ] Step: read_SOR_HOM_SMT_BDGT_PARM
-- Table: SOR_HOM_SMT_BDGT_PARM
-- Connection: SOR
SELECT * FROM SOR_HOM_SMT_BDGT_PARM;

-- [TABLE_READ] Step: read_SOR_HOM_SMT_BDGT_PARM_STS
-- Table: SOR_HOM_SMT_BDGT_PARM
-- Connection: SOR
SELECT * FROM SOR_HOM_SMT_BDGT_PARM;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_BUD_COPY
select v.bdgt_prcs_year
	   ,v.copy_code
	   ,v.copy_ver_num
	   ,v.bdgt_copy_desp
	   ,v.mth_bdgt_copy
from   (
select distinct c.prcs_year as bdgt_prcs_year
			 ,c.copy_code
			 ,c.copy_ver_num
			 ,DECODE(c.copy_ver_num,-1, c.copy_code||' FINAL', c.copy_code||c.copy_ver_num)||' '||c.prcs_year bdgt_copy_desp
	   	 ,NVL((select distinct first_value(copy_code||copy_ver_num) over (order by copy_ver_num desc)
				    from    SOR_HOM_BUD_COPY
				    where 	prcs_year = c.prcs_year
						and	    bdgt_exrc_code = '1'
						and			copy_code = c.copy_code
						and			DECODE(copy_ver_num,-1,99,copy_ver_num) <
										(select MIN(DECODE(copy_ver_num,-1,99,copy_ver_num))
								 		from    SOR_HOM_BUD_COPY
								 		where 	prcs_year = c.prcs_year
								 		and     bdgt_exrc_code = '0'
								 		and	 		copy_code = c.copy_code
								 		and	 		DECODE(copy_ver_num,-1,99,copy_ver_num) > DECODE(c.copy_ver_num,-1,99,c.copy_ver_num))
										),
						(select copy_code||copy_ver_num
						from 		SOR_HOM_BUD_COPY
						where 	prcs_year = c.prcs_year
						and 		bdgt_exrc_code = '1'
						and 		copy_code = c.copy_code
						and 		copy_ver_num = c.copy_ver_num)
				 ) mth_bdgt_copy
from	SOR_HOM_BUD_COPY c
	   	,SOR_HOM_SMT_BDGT_PARM m, SOR_HOM_SMT_BDGT_PARM_sts mm
where c.last_Rec_txn_type_code is null
and	  m.last_Rec_txn_type_code is null
and	  mm.last_Rec_txn_type_code is null
and   m.bdgt_parm_key = mm.bdgt_parm_key
and		m.bdgt_parm_code in ('APRV_BDGT_COPY', 'RVS_BDGT_COPY')
and 	c.bdgt_exrc_code = '0'
and		c.prcs_year||c.copy_code||c.copy_ver_num = mm.bdgt_parm_val_text
and  TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN mm.bgn_date AND mm.end_date
) v;

