-- Connection: SOR
SELECT * FROM SOR_HOM_REF_PMS_DSTR;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_REF_PMS_DSTR
select d.dstr_code, dd.dstr_name, nvl(p.pms_dstr_code, 'OTHR') pms_dstr_code,
       nvl(pp.PMS_DSTR_NAME, 'Others') pms_dstr_name, 
	   decode(d.dstr_code, 'OR', 1000, 'UN', 2000, dd.DISP_SEQ_NUM) dstr_disp_seq_num, 
	   decode(d.dstr_code, 'OR', 1000, 'UN', 1000, pp.DISP_SEQ_NUM) pms_dstr_disp_seq_num
  from SOR_HOM_REF_DSTR d, SOR_HOM_REF_DSTR_STS dd, 
       SOR_HOM_REF_PMS_DSTR p, SOR_HOM_REF_PMS_DSTR_STS pp
 where dd.PMS_DSTR_CODE = p.PMS_DSTR_CODE(+)
       and d.dstr_key = dd.dstr_key 
       and p.pms_dstr_key = pp.pms_dstr_key(+)
	   and d.dstr_key > 0
	   and (TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN dd.bgn_date AND dd.end_date OR dd.bgn_date is null)
	   and (TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN pp.bgn_date AND pp.end_date OR PP.bgn_date is null)
 union 
select 'OTHR' dstr_code, 'Others' dstr_name, 'OTHR' pms_dstr_code,
       'Others' pms_dstr_name, 10000 dstr_disp_seq_num, 1000
       pms_dstr_disp_seq_num
  from dual;

