-- Connection: SOR
SELECT * FROM SOR_HOM_SMT_SUB_DIV;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_SMT_ORG_STRC
select d.SUB_DIV_NAME,
s.SCTN_NAME,
o.PROJ_MGR_NAME,
ds.DISP_SEQ_NUM sub_div_disp_seq_num,
ss.DISP_SEQ_NUM sctn_disp_seq_num,
os.DISP_SEQ_NUM mgr_disp_seq_num
from SOR_HOM_SMT_SUB_DIV d, SOR_HOM_SMT_SUB_DIV_STS ds, SOR_HOM_SMT_SCTN s, SOR_HOM_SMT_SCTN_STS ss, SOR_HOM_SMT_ORG_STRC o, SOR_HOM_SMT_ORG_STRC_STS os
where d.SUB_DIV_KEY = ds.SUB_DIV_KEY
and d.SUB_DIV_KEY = ss.SUB_DIV_KEY
and s.SCTN_KEY = ss.SCTN_KEY
and s.SCTN_KEY = os.SCTN_KEY
and o.ORG_STRC_KEY = os.ORG_STRC_KEY
and d.LAST_REC_TXN_TYPE_CODE is NULL
and s.LAST_REC_TXN_TYPE_CODE is NULL
--and o.LAST_REC_TXN_TYPE_CODE is NULL
and ds.LAST_REC_TXN_TYPE_CODE is NULL
and ss.LAST_REC_TXN_TYPE_CODE is NULL
and os.LAST_REC_TXN_TYPE_CODE is NULL
and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN ds.bgn_date AND ds.end_date
and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN ss.bgn_date AND ss.end_date
and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN os.bgn_date AND os.end_date
union
select 'Others' sub_div_name, 'Others' sctn_name, 'OTHR' proj_mgr_name, 9999 sub_div_disp_seq_num, 9999 sctn_disp_seq_num, 9999 mgr_disp_seq_num from dual;

