SELECT * FROM SOR_HOM_CON_CNTR_CLASS;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_CON_CNTR_TYPE
select cl.cntr_class_code, c.cntr_type_code, cs.cntr_type_desp, dense_rank()
  over (
		 order by c.cntr_class_key, c.cntr_type_code, cs.cntr_type_desp
       ) cntr_type_disp_seq_num
  from SOR_HOM_CON_CNTR_TYPE c, SOR_HOM_CON_CNTR_TYPE_STS cs, SOR_HOM_CON_CNTR_CLASS cl
 where c.CNTR_TYPE_KEY = cs.CNTR_TYPE_KEY and
 cl.CNTR_CLASS_KEY = c.CNTR_CLASS_KEY and
 c.LAST_REC_TXN_TYPE_CODE is null and
 cs.LAST_REC_TXN_TYPE_CODE is null and
 cl.LAST_REC_TXN_TYPE_CODE is null and
 TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN cs.bgn_date AND cs.end_date;

