-- [TABLE_READ] Step: read_SOR_HOM_PRG_SNSH
-- Table: SOR_HOM_PRG_SNSH
-- Connection: SOR
SELECT * FROM SOR_HOM_PRG_SNSH;

-- [SOURCE_QUALIFIER] Step: apply_SQ_SOR_HOM_PRG_SNSH_PROJ_STS
select
pj.proj_hom_bk
, s.snsh_hom_key snsh_key
, d.dstr_code
, pp.proj_num
, pp.dev_type_code
, pp.phase_code
, pp.proj_ttl
, dense_rank() over (order by ss.snsh_year, ss.snsh_mth, pp.proj_ttl, p.proj_key) snsh_proj_disp_seq_num
from SOR_HOM_PRG_SNSH_PROJ p, SOR_HOM_PRG_SNSH_PROJ_sts pp, SOR_HOM_PRG_SNSH s, SOR_HOM_PRG_SNSH_STS ss, 
	 SOR_HOM_REF_DSTR d, SOR_HOM_PRJ_PROJ pj
where s.last_rec_txn_type_code is null
and ss.last_rec_txn_type_code is null
and p.last_rec_txn_type_code is null
and pp.last_rec_txn_type_code is null
and ss.snsh_type_code = 'FINAL'
and ss.snsh_qtr_ind = 'N'
and s.snsh_key = p.snsh_key
and s.SNSH_KEY = ss.SNSH_KEY
and p.PGM_LVL_SNSH_PROJ_KEY = pp.PGM_LVL_SNSH_PROJ_KEY
and d.dstr_key = pp.dstr_key
and pj.proj_key = p.proj_key
and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN pp.bgn_date AND pp.end_date
and TO_DATE ($$v_snsh_date, 'YYYYMMDD') BETWEEN ss.bgn_date AND ss.end_date;

